using System.Collections;
using System.Collections.Generic;
using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RecycleAction", menuName = "Data/Battle/Battle Actions/Hevelius/Recycle Action")]
public class RecycleAction : BattleAction
{
	[Header("Companions List")]
	[SerializeField]
	private CompanionsListsList companionsListsList;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private CompanionRewardStartingEffect companionRewardStartingEffect;

	[SerializeField]
	private RepairAction repairAction;

	[SerializeField]
	private BattleAction empowerEffectAction;

	[SerializeField]
	private EmpowerEffect empowerEffect;

	[SerializeField]
	private float delayToRecycle = 1.2f;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return currentCompanions.RuntimeCompanions.Count > 0;
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		bool flag = target.transform.parent.name == "CompanionBroken";
		GameObject gameObject = (flag ? target.transform.parent.parent.GetFirstChild().gameObject : target);
		if (!flag)
		{
			gameObject.GetComponent<CompanionEffects>().ActivateAreaPurifyCorruptOnBreakEffects(recycle: true);
		}
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(RecycleCompanionCoroutine(target, source, flag, gameObject));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator RecycleCompanionCoroutine(GameObject target, GameObject source, bool isCompanionBroken, GameObject companionAliveGameObject)
	{
		if (IsVFXEnabled())
		{
			PlaySFX();
			SpawnVFX(GetVFXOwnerPosition(target), 5f);
			yield return new WaitForSeconds(delayToRecycle);
		}
		CompanionInitializer component = companionAliveGameObject.GetComponent<CompanionInitializer>();
		int companionIndex = currentCompanions.GetCompanionIndex(component.RuntimeCompanion);
		int companionLevel = currentCompanions.RuntimeCompanions[companionIndex].CompanionLevel;
		RuntimeCompanion runtimeCompanion = GetRuntimeCompanion(companionLevel, RandomCompanionEnum.RECYCLE);
		currentCompanions.RuntimeCompanions[companionIndex] = runtimeCompanion;
		CompanionEffects component2 = companionAliveGameObject.GetComponent<CompanionEffects>();
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RecycledSentinelAmount++;
		if (isCompanionBroken)
		{
			CheckForBlessingsWithSentinelStartingEffects(runtimeCompanion);
			repairAction.InitializeCompanion(target, initializeCompanionEntirely: false, companionIndex);
		}
		else
		{
			CheckForBlessingsWithSentinelStartingEffects(runtimeCompanion);
			List<StartingEffect> combinedEffects = runtimeCompanion.GetCombinedEffects();
			for (int i = 0; i < combinedEffects.Count; i++)
			{
				if (combinedEffects[i].Effect == component2.CompanionEffectsList.BoostEffect)
				{
					component2.SetWasBoosted(value: true);
				}
			}
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.BrokenSentinelAmount++;
			ReferenceSingleton<HeveliusOmensHandler>.Instance.ActivateEnergyAbsorberOmen();
			component2.RemoveAllEffectsWithCallbacks();
		}
		component.InitializeCompanionEntirelyWithoutStoreDiceRecycle(runtimeCompanion);
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.NewCompanionAcquired(runtimeCompanion.CompanionData);
		int num = component2.IsEffectActiveGetAmount(empowerEffect, activateFeedback: false);
		int num2 = Mathf.FloorToInt((float)ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RecycledSentinelAmount / 2f);
		if (num2 > 0)
		{
			empowerEffectAction.CastTargetAmount(companionAliveGameObject, num2 - num, source);
		}
		repairAction.RecycleActionSpawnCompanionDice(companionAliveGameObject, source);
		if (!isCompanionBroken)
		{
			component2.SetJustRecycled(value: false);
		}
	}

	private void CheckForBlessingsWithSentinelStartingEffects(RuntimeCompanion runtimeCompanion)
	{
		for (int i = 0; i < ReferenceSingleton<MiscOmensHandler>.Instance.SentinelStartingEffectOmenList.Count; i++)
		{
			StartingEffect startingEffect = ReferenceSingleton<MiscOmensHandler>.Instance.SentinelStartingEffectOmenList[i];
			bool flag = false;
			for (int j = 0; j < runtimeCompanion.StartingEffectsAdded.Count; j++)
			{
				if (runtimeCompanion.StartingEffectsAdded[i].Effect == startingEffect.Effect)
				{
					runtimeCompanion.StartingEffectsAdded[i].IncreaseEffectAmount(startingEffect.EffectAmount);
					flag = true;
				}
			}
			if (!flag)
			{
				runtimeCompanion.StartingEffectsAdded.Add(startingEffect);
			}
		}
	}

	private CompanionData GetRandomCompanion(RandomCompanionEnum randomCompanionEnum)
	{
		List<CompanionData> list = new List<CompanionData>();
		for (int i = 0; i < companionsListsList.CompanionsLists.Length; i++)
		{
			list.AddRange(companionsListsList.CompanionsLists[i].Companions);
		}
		ReferenceSingleton<AssetsReference>.Instance.CompanionReward.CheckRemoveSentinelsFromList(list);
		switch (randomCompanionEnum)
		{
		case RandomCompanionEnum.RECYCLE:
			list.RemoveAll((CompanionData companion) => companionsListsList.CompanionsThatCantBePickedOnRecycleAction.Contains(companion));
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.GetCharacterLevel() == 0)
			{
				list.RemoveAll((CompanionData companion) => companion.CompanionID.Replace(" ", "") == "UnknownDevice");
			}
			break;
		case RandomCompanionEnum.EMULATE:
			list.RemoveAll((CompanionData companion) => companionsListsList.CompanionsThatCantBePickedOnEmulate.Contains(companion));
			break;
		case RandomCompanionEnum.NO_UNKNOWN_DEVICE:
			list.RemoveAll((CompanionData companion) => companion.CompanionID.Replace(" ", "") == "UnknownDevice");
			break;
		}
		return list.PopRandom();
	}

	public RuntimeCompanion GetRuntimeCompanion(int companionLevel, RandomCompanionEnum randomCompanionEnum)
	{
		CompanionData randomCompanion = GetRandomCompanion(randomCompanionEnum);
		if (randomCompanion.CompendiumItemState == CompendiumItemState.Undiscovered)
		{
			List<CompanionData> list = new List<CompanionData>();
			list.Add(randomCompanion);
			companionsListsList.SentinelsDiscovered(list);
		}
		RuntimeCompanion runtimeCompanion = new RuntimeCompanion(randomCompanion, companionLevel);
		List<StartingEffect> sentinelStartingEffectsRunModifiers = ReferenceSingleton<RunModifiersManager>.Instance.SentinelStartingEffectsRunModifiers;
		for (int i = 0; i < sentinelStartingEffectsRunModifiers.Count; i++)
		{
			runtimeCompanion.AddStartingEffect(sentinelStartingEffectsRunModifiers[i]);
		}
		StartingEffect[] startingEffects = companionRewardStartingEffect.CompanionRewardStartingEffects[companionLevel].StartingEffects;
		if (startingEffects.Length != 0)
		{
			runtimeCompanion.AddStartingEffect(startingEffects.PickRandom());
		}
		return runtimeCompanion;
	}

	public RuntimeCompanion GetRuntimeCompanion(int companionLevel, CompanionData companionData)
	{
		if (companionData.CompendiumItemState == CompendiumItemState.Undiscovered)
		{
			List<CompanionData> list = new List<CompanionData>();
			list.Add(companionData);
			companionsListsList.SentinelsDiscovered(list);
		}
		return new RuntimeCompanion(companionData, companionLevel);
	}
}
